import React, { useState, useEffect } from "react";
import {
  GraduationCap,
  Briefcase,
  BarChart3,
  UserCheck,
  Zap,
  ArrowRight,
  CheckCircle2,
  Mail,
  Menu,
  CalendarDays,
  User,
  X,
  LogOut,
  Settings,
  Bell,
  Search,
  MessageCircle
} from 'lucide-react';

const neonColor = "#00D9FF";
const neonShadow = "shadow-cyan-400/50";
const neonBorder = "border-cyan-400";
const neonText = "text-cyan-400";
const neonBg = "bg-cyan-400/10";
const neonGlow = "shadow-cyan-400/25";

const profilePic = "https://randomuser.me/api/portraits/men/32.jpg"; // Example profile photo

const menuTabs = [
  { name: "MAILS", icon: Mail },
  { name: "UPCOMING EVENTS", icon: CalendarDays },
  { name: "UPDATE PROFILE", icon: User }
];

const mails = [
  { subject: "Internship Offer", from: "Google", time: "1h ago", unread: true },
  { subject: "Interview Reminder", from: "Amazon", time: "Yesterday", unread: false },
  { subject: "Profile Update", from: "CampusConnect", time: "2 days ago", unread: false }
];

const events = [
  { title: "Amazon Interview", date: "2025-09-25", time: "10:00 AM", location: "Room 201" },
  { title: "Career Fair", date: "2025-09-28", time: "2:00 PM", location: "Main Hall" }
];

const StudentDash = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activeTab, setActiveTab] = useState(menuTabs[0].name);

  // Loading skeletons state
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 1200);
    return () => clearTimeout(timer);
  }, []);

  // Toast notification state
  const [toast, setToast] = useState(null);
  function showToast(msg) {
    setToast(msg);
    setTimeout(() => setToast(null), 3000);
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white relative overflow-hidden font-sans">
      {/* Animated background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-gray-800 to-black"></div>
        <div className="absolute top-1/4 left-1/4 w-96 h-96 rounded-full opacity-20 blur-3xl animate-pulse" style={{ backgroundColor: neonColor }}></div>
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 rounded-full opacity-15 blur-3xl animate-pulse" style={{ backgroundColor: neonColor, animationDelay: '2s' }}></div>
      </div>
      {/* Grid overlay */}
      <div className="absolute inset-0 opacity-5 pointer-events-none">
        <div className="h-full w-full" style={{
          backgroundImage: `linear-gradient(${neonColor}22 1px, transparent 1px), linear-gradient(90deg, ${neonColor}22 1px, transparent 1px)`,
          backgroundSize: '20px 20px'
        }}></div>
      </div>

      {/* Navbar */}
      <nav className="relative z-20 w-full flex items-center justify-between px-8 py-4 bg-gray-900/80 border-b border-gray-800 shadow-lg">
        <div className="flex items-center space-x-3">
          <GraduationCap className={`h-8 w-8 ${neonText} drop-shadow-lg`} />
          <span className={`font-bold text-2xl ${neonText}`}>CampusConnect</span>
        </div>
        <div className="flex items-center space-x-6">
          <button className="p-2 rounded-xl bg-gray-800 hover:bg-gray-700 transition">
            <Bell className="h-6 w-6 text-cyan-400" />
          </button>
          <button className="p-2 rounded-xl bg-gray-800 hover:bg-gray-700 transition">
            <Settings className="h-6 w-6 text-cyan-400" />
          </button>
          <div className="flex items-center space-x-3">
            <img
              src={profilePic}
              alt="Profile"
              className={`h-10 w-10 rounded-full border-2 ${neonBorder} ${neonGlow} object-cover`}
            />
            <span className="font-semibold text-white hidden md:inline">John Doe</span>
          </div>
          <button
            className={`p-2 rounded-xl border-2 ${neonBorder} ${neonGlow} bg-gray-800 hover:bg-gray-700 transition`}
            onClick={() => setDrawerOpen(true)}
            aria-label="Open menu"
          >
            <Menu className={`h-6 w-6 ${neonText}`} />
          </button>
        </div>
      </nav>

      {/* Sidebar Drawer */}
      <div
        className={`fixed top-0 right-0 h-full w-80 bg-gray-900/95 border-l-2 ${neonBorder} ${neonGlow} z-30 transform transition-transform duration-300 ${
          drawerOpen ? "translate-x-0" : "translate-x-full"
        }`}
        style={{ backdropFilter: "blur(8px)" }}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800">
          <div className="flex items-center space-x-3">
            <img
              src={profilePic}
              alt="Profile"
              className={`h-9 w-9 rounded-full border-2 ${neonBorder} ${neonGlow} object-cover`}
            />
            <span className={`font-semibold text-lg ${neonText}`}>John Doe</span>
          </div>
          <button
            className="p-2 rounded-lg hover:bg-gray-800 transition"
            onClick={() => setDrawerOpen(false)}
            aria-label="Close menu"
          >
            <X className="h-6 w-6 text-gray-400" />
          </button>
        </div>
        <div className="flex flex-col px-6 py-6 space-y-2">
          {menuTabs.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.name}
                className={`flex items-center w-full px-4 py-3 rounded-xl font-semibold text-left transition-all duration-200
                  ${activeTab === tab.name ? `${neonBg} ${neonText} border-2 ${neonBorder}` : "text-gray-300 hover:bg-gray-800"}
                `}
                onClick={() => setActiveTab(tab.name)}
              >
                <Icon className={`h-5 w-5 mr-3 ${activeTab === tab.name ? neonText : "text-gray-400"}`} />
                {tab.name}
              </button>
            );
          })}
        </div>
        <div className="px-6 py-4 border-t border-gray-800 mt-auto">
          <button className="w-full py-2 rounded-xl bg-gradient-to-r from-cyan-400 to-emerald-400 text-gray-900 font-bold shadow-lg hover:scale-105 transition flex items-center justify-center gap-2">
            <LogOut className="h-5 w-5" />
            Logout
          </button>
        </div>
      </div>
      {/* Overlay for drawer */}
      {drawerOpen && (
        <div
          className="fixed inset-0 z-20 bg-black/40"
          onClick={() => setDrawerOpen(false)}
        />
      )}

      {/* Main Content */}
      <div className="relative z-10 min-h-screen flex flex-col items-center px-6 py-12">
        {/* Header */}
        <div className="max-w-3xl w-full mb-10">
          <div className="flex items-center space-x-4 mb-6">
            <div className={`p-4 bg-gray-800 border-2 ${neonBorder} rounded-2xl ${neonGlow}`}>
              <GraduationCap className="h-12 w-12" style={{ color: neonColor }} />
            </div>
            <h1 className="text-4xl font-bold bg-gradient-to-r from-cyan-400 via-emerald-400 to-orange-400 bg-clip-text text-transparent animate-pulse">
              Welcome, Student!
            </h1>
          </div>
          <p className="text-lg text-gray-300">
            Your personalized dashboard for internships, progress, and campus updates.
          </p>
        </div>

        {/* Stats Cards with Loading Skeletons */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-5xl mb-12">
            {[1,2,3].map(i => (
              <div key={i} className="bg-gray-800/90 rounded-2xl border-2 border-gray-700 p-8 flex flex-col items-center animate-pulse">
                <div className="h-10 w-10 bg-gray-700 rounded-full mb-3"></div>
                <div className="h-6 w-32 bg-gray-700 rounded mb-2"></div>
                <div className="h-8 w-20 bg-gray-700 rounded mb-1"></div>
                <div className="h-4 w-24 bg-gray-700 rounded"></div>
              </div>
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-5xl mb-12">
            <div className={`bg-gray-800/90 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-8 flex flex-col items-center shadow-xl`}>
              <Briefcase className="h-10 w-10 mb-3" style={{ color: neonColor }} />
              <h2 className={`text-2xl font-bold mb-2 ${neonText}`}>Internships Applied</h2>
              <p className="text-4xl font-bold text-white mb-1">7</p>
              <span className="text-gray-400">This semester</span>
            </div>
            <div className={`bg-gray-800/90 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-8 flex flex-col items-center shadow-xl`}>
              <BarChart3 className="h-10 w-10 mb-3" style={{ color: neonColor }} />
              <h2 className={`text-2xl font-bold mb-2 ${neonText}`}>Progress</h2>
              <p className="text-4xl font-bold text-white mb-1">85%</p>
              <span className="text-gray-400">Profile completed</span>
            </div>
            <div className={`bg-gray-800/90 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-8 flex flex-col items-center shadow-xl`}>
              <UserCheck className="h-10 w-10 mb-3" style={{ color: neonColor }} />
              <h2 className={`text-2xl font-bold mb-2 ${neonText}`}>Mentor Meetings</h2>
              <p className="text-4xl font-bold text-white mb-1">3</p>
              <span className="text-gray-400">Upcoming</span>
            </div>
          </div>
        )}

        {/* Quick Actions */}
        <div className="w-full max-w-4xl mb-12">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className={`bg-gray-800/80 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 flex items-center justify-between shadow-lg`}>
              <div>
                <h3 className={`text-xl font-bold mb-2 ${neonText}`}>Browse Internships</h3>
                <p className="text-gray-400 mb-2">Find new opportunities and apply directly.</p>
                <button className={`py-2 px-4 bg-gray-900 border-2 ${neonBorder} text-white font-bold rounded-xl transition-all duration-300 hover:scale-105 ${neonGlow} hover:${neonBg} flex items-center`}>
                  <Zap className="h-5 w-5 mr-2" style={{ color: neonColor }} />
                  Explore
                  <ArrowRight className="h-5 w-5 ml-2" />
                </button>
              </div>
              <Briefcase className="h-14 w-14" style={{ color: neonColor }} />
            </div>
            <div className={`bg-gray-800/80 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 flex items-center justify-between shadow-lg`}>
              <div>
                <h3 className={`text-xl font-bold mb-2 ${neonText}`}>Track Applications</h3>
                <p className="text-gray-400 mb-2">Monitor your application status and interview schedules.</p>
                <button className={`py-2 px-4 bg-gray-900 border-2 ${neonBorder} text-white font-bold rounded-xl transition-all duration-300 hover:scale-105 ${neonGlow} hover:${neonBg} flex items-center`}>
                  <CheckCircle2 className="h-5 w-5 mr-2" style={{ color: neonColor }} />
                  Track
                  <ArrowRight className="h-5 w-5 ml-2" />
                </button>
              </div>
              <BarChart3 className="h-14 w-14" style={{ color: neonColor }} />
            </div>
          </div>
        </div>

        {/* Tabbed Content */}
        <div className="w-full max-w-4xl mb-12">
          <div className={`bg-gray-800/80 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-8 shadow-lg`}>
            <div className="flex items-center mb-6">
              {menuTabs.map(tab => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.name}
                    className={`flex items-center px-4 py-2 rounded-xl font-semibold mr-4 transition-all duration-200
                      ${activeTab === tab.name ? `${neonBg} ${neonText} border-2 ${neonBorder}` : "text-gray-300 hover:bg-gray-800"}
                    `}
                    onClick={() => setActiveTab(tab.name)}
                  >
                    <Icon className={`h-5 w-5 mr-2 ${activeTab === tab.name ? neonText : "text-gray-400"}`} />
                    {tab.name}
                  </button>
                );
              })}
            </div>
            {/* Tab Content */}
            {activeTab === "MAILS" && (
              <div>
                <div className="flex items-center mb-4">
                  <Search className="h-5 w-5 text-gray-400 mr-2" />
                  <input
                    type="text"
                    placeholder="Search mails..."
                    className="bg-gray-900 border border-gray-700 rounded-xl px-3 py-2 text-gray-200 w-full focus:outline-none focus:border-cyan-400"
                  />
                </div>
                <ul className="divide-y divide-gray-800">
                  {mails.map((mail, idx) => (
                    <li key={idx} className="py-4 flex items-center">
                      <Mail className={`h-6 w-6 mr-3 ${mail.unread ? neonText : "text-gray-400"}`} />
                      <div className="flex-1">
                        <span className={`font-bold ${mail.unread ? neonText : "text-gray-200"}`}>{mail.subject}</span>
                        <span className="ml-2 text-gray-400">from {mail.from}</span>
                      </div>
                      <span className="text-xs text-gray-500">{mail.time}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {activeTab === "UPCOMING EVENTS" && (
              <div>
                <ul className="space-y-4">
                  {events.map((event, idx) => (
                    <li key={idx} className="flex items-center justify-between bg-gray-900/60 rounded-xl p-4 border border-cyan-900">
                      <div>
                        <span className={`font-bold text-lg ${neonText}`}>{event.title}</span>
                        <div className="text-gray-400 text-sm">{event.date} • {event.time}</div>
                        <div className="text-gray-500 text-xs">{event.location}</div>
                      </div>
                      <CalendarDays className={`h-8 w-8 ${neonText}`} />
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {activeTab === "UPDATE PROFILE" && (
              <div>
                <form
                  className="space-y-6 max-w-md"
                  onSubmit={e => {
                    e.preventDefault();
                    showToast("Profile updated!");
                  }}
                >
                  <div>
                    <label className="block text-gray-400 mb-1">Full Name</label>
                    <input type="text" defaultValue="John Doe" className="w-full px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  </div>
                  <div>
                    <label className="block text-gray-400 mb-1">Email</label>
                    <input type="email" defaultValue="john.doe@college.edu" className="w-full px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  </div>
                  <div>
                    <label className="block text-gray-400 mb-1">Major</label>
                    <input type="text" defaultValue="Computer Science" className="w-full px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  </div>
                  <button type="submit" className={`w-full py-3 rounded-xl bg-gradient-to-r from-cyan-400 to-emerald-400 text-gray-900 font-bold shadow-lg hover:scale-105 transition`}>
                    Save Changes
                  </button>
                </form>
              </div>
            )}
          </div>
        </div>

        {/* Recent Activity */}
        <div className="w-full max-w-3xl mb-12">
          <div className={`bg-gray-800/80 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 shadow-lg`}>
            <h3 className={`text-xl font-bold mb-4 ${neonText}`}>Recent Activity</h3>
            <ul className="space-y-4">
              <li className="flex items-center">
                <CheckCircle2 className="h-5 w-5 mr-3" style={{ color: neonColor }} />
                <span className="text-gray-300">Applied to <span className={neonText}>Google Summer Internship</span></span>
                <span className="ml-auto text-xs text-gray-500">2 days ago</span>
              </li>
              <li className="flex items-center">
                <CheckCircle2 className="h-5 w-5 mr-3" style={{ color: neonColor }} />
                <span className="text-gray-300">Scheduled interview with <span className={neonText}>Amazon</span></span>
                <span className="ml-auto text-xs text-gray-500">Yesterday</span>
              </li>
              <li className="flex items-center">
                <CheckCircle2 className="h-5 w-5 mr-3" style={{ color: neonColor }} />
                <span className="text-gray-300">Profile updated</span>
                <span className="ml-auto text-xs text-gray-500">Just now</span>
              </li>
            </ul>
          </div>
        </div>

        {/* Sticky Quick Actions Bar (Mobile Only) */}
        <div className="fixed bottom-0 left-0 w-full bg-gray-900/90 border-t border-cyan-400 flex justify-around py-2 md:hidden z-40">
          <button className="flex flex-col items-center text-cyan-400" onClick={() => setActiveTab("MAILS")}>
            <Mail className="h-6 w-6" />
            <span className="text-xs">Mails</span>
          </button>
          <button className="flex flex-col items-center text-cyan-400" onClick={() => setActiveTab("UPCOMING EVENTS")}>
            <CalendarDays className="h-6 w-6" />
            <span className="text-xs">Events</span>
          </button>
          <button className="flex flex-col items-center text-cyan-400" onClick={() => setActiveTab("MENTOR CHAT")}>
            <MessageCircle className="h-6 w-6" />
            <span className="text-xs">Chat</span>
          </button>
        </div>

        {/* Footer */}
        <div className="border-t border-gray-800 bg-gray-900/50 backdrop-blur-sm py-8 w-full mt-auto">
          <div className="text-center">
            <div className="flex justify-center items-center space-x-4 mb-4">
              <div className="h-px w-16 bg-gradient-to-r from-transparent to-cyan-400"></div>
              <span className="text-gray-400 font-medium">SECURE • RELIABLE • FAST</span>
              <div className="h-px w-16 bg-gradient-to-l from-transparent to-emerald-400"></div>
            </div>
            <p className="text-gray-500">
              Need help?{' '}
              <button className="text-cyan-400 hover:text-cyan-300 font-semibold transition-colors duration-300">
                support@campusconnect.edu
              </button>
            </p>
          </div>
        </div>
      </div>
      {/* Toast Notification */}
      {toast && (
        <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 bg-cyan-400 text-gray-900 px-6 py-3 rounded-xl shadow-lg font-bold z-50 animate-bounce">
          {toast}
        </div>
      )}
      {/* End Main Content */}
    </div>
  );
};

export default StudentDash;
